const $=id=>document.getElementById(id), stage=$("cnStage"), subject=$("cnSubject"), search=$("cnSearch"), reader=$("cnReader");
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
