flow:'<g fill="#edf3fb" stroke="#123b75" stroke-width="2"><rect x="30" y="55" width="145" height="65" rx="10"/><rect x="235" y="55" width="145" height="65" rx="10"/><rect x="440" y="55" width="145" height="65" rx="10"/></g><g fill="#071a3d" text-anchor="middle" font-size="15"><text x="102" y="93">Input</text><text x="307" y="93">Process</text><text x="512" y="93">Output</text></g><g stroke="#123b75" stroke-width="2"><path d="M175 87 H230 M220 80 L230 87 L220 94 M380 87 H435 M425 80 L435 87 L425 94"/></g>',
percent:'<rect x="30" y="35" width="560" height="40" rx="7" fill="#e7eef8"/><rect x="30" y="35" width="476" height="40" rx="7" fill="#4c79b8"/><text x="30" y="105" font-size="15" fill="#071a3d">100% original amount</text><text x="510" y="105" font-size="15" fill="#071a3d">85% after 15% reduction</text>',
paragraph:'<rect x="25" y="20" width="570" height="145" rx="10" fill="#edf3fb" stroke="#123b75"/><g fill="#123b75" font-size="15"><text x="45" y="52" font-weight="bold">Topic sentence</text><text x="45" y="82">Explanation and evidence</text><text x="45" y="112">Example or supporting detail</text><text x="45" y="142" font-weight="bold">Linking sentence</text></g>',
states:'<g text-anchor="middle" fill="#071a3d" font-size="14"><rect x="25" y="35" width="160" height="120" rx="8" fill="#edf3fb" stroke="#123b75"/><rect x="230" y="35" width="160" height="120" rx="8" fill="#edf3fb" stroke="#123b75"/><rect x="435" y="35" width="160" height="120" rx="8" fill="#edf3fb" stroke="#123b75"/><text x="105" y="25">Solid</text><text x="310" y="25">Liquid</text><text x="515" y="25">Gas</text></g>'+Array.from({length:9},(_,i)=>'<circle cx="'+(55+(i%3)*45)+'" cy="'+(65+Math.floor(i/3)*32)+'" r="5" fill="#123b75"/>').join("")+Array.from({length:9},(_,i)=>'<circle cx="'+(255+(i%3)*45+(i%2)*5)+'" cy="'+(65+Math.floor(i/3)*32+(i%3)*3)+'" r="5" fill="#123b75"/>').join("")+Array.from({length:8},(_,i)=>'<circle cx="'+(465+(i*47)%110)+'" cy="'+(55+(i*31)%85)+'" r="5" fill="#123b75"/>').join("")+'<g stroke="#123b75" stroke-width="2"><path d="M185 95 H225 M215 88 L225 95 L215 102 M390 95 H430 M420 88 L430 95 L420 102"/></g>',
